insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('746b1fe5-9312-4688-8acf-78d313a7752a', 'fr', 'Tu entres dans un lieu et tu te présentes à plusieurs personnes. Plus tard, tu l’abordes. Qu’est-ce qui a aidé ?', '["Elle est plus ouverte grâce à la preuve sociale que tu as créée", "Rien : le statut n’influence pas la réceptivité", "Tu dois encore compenser un statut faible", "L’approche paraît forcée"]'::jsonb, 'Les échanges positifs font monter ton statut, ce qui la rend plus réceptive.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c790b664-f094-409a-9440-448401e0ec8e', 'fr', 'Comment se construire vite un statut social dans un nouvel environnement ?', '["Présenter les gens les uns aux autres", "Échanger avec respect avec le personnel ou les hôtes", "Te concentrer uniquement sur une seule personne", "Apporter une énergie positive au groupe"]'::jsonb, 'Apporter quelque chose au tissu social fait monter ton statut plus vite que de poursuivre une seule personne.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d799275-6cc6-4451-9db7-bfb0e563f9bc', 'fr', 'Qu’est-ce qui rend vraiment un homme intéressant dans une conversation ?', '["Vivre une vie qui produit des histoires et du recul", "Avoir des opinions tranchées", "Être drôle sur commande", "Parler de lui avec assurance"]'::jsonb, 'Une vie intéressante produit de vraies expériences qui attirent naturellement les gens.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8654d59-aeba-4ca6-b2c9-c6824582ae10', 'fr', 'À quoi voit-on que quelqu’un a une vie intéressante ?', '["Il a naturellement des histoires tirées de vraies expériences", "Il pose de meilleures questions, par vraie curiosité", "Il parle avec passion de ses projets ou de ses centres d’intérêt du moment", "Toutes les réponses ci-dessus"]'::jsonb, 'Une vie intéressante produit de vraies expériences qui attirent naturellement les gens.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8dd4c710-136c-4930-a752-e6a21ba5f5ac', 'fr', 'Comment une vie intéressante change-t-elle la dynamique d’une conversation ?', '["Elle transforme la discussion en performance", "Elle fournit des sujets naturels sans avoir à creuser", "Elle crée une énergie magnétique à partir de vraies expériences"]'::jsonb, 'Une vie intéressante produit des échanges prenants et sans effort.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a96beb76-cf2b-44bb-8339-887ee43c1e0e', 'fr', 'Pourquoi le mystère aide-t-il l’attirance ?', '["L’incertitude la garde mentalement impliquée et curieuse", "Le cerveau fait plus attention à ce qu’il ne peut pas cerner entièrement", "Ça lui laisse de la place pour te découvrir au lieu de la noyer d’informations", "Toutes les réponses ci-dessus"]'::jsonb, 'Le mystère garde l’attention en éveil en laissant de la place à la curiosité et à la découverte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87f62533-abcc-4fdd-ab12-24b45f5f4be0', 'fr', 'Elle te demande ce que tu fais dans la vie. Quelle réponse crée le plus de mystère ?', '["Détailler ton travail et tes projets", "Dire « Un peu de tout, surtout des trucs créatifs », puis lui poser une question sur elle", "Énumérer tout ton parcours professionnel", "Dire « Rien d’intéressant » et changer de sujet"]'::jsonb, 'Partage juste assez pour intriguer, en laissant de la place à sa curiosité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f45fc9f5-e0a3-4d7b-87bc-840a0f414623', 'fr', 'Que se passe-t-il quand tu t’expliques trop au début d’une conversation ?', '["Son imagination reste activement en éveil", "Il ne lui reste rien à découvrir ni à imaginer", "La curiosité s’éteint à mesure que le portrait se complète"]'::jsonb, 'Tout dévoiler enlève l’incertitude, ce qui réduit son implication mentale.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59011032-6b21-4d79-aaf3-ebe1fcb14211', 'fr', 'Comment ton entourage influence-t-il ton assurance avec les femmes ?', '["Un comportement social paraît normal ou pas selon ton environnement", "Les amis t’apprennent directement à séduire", "L’assurance est biologiquement contagieuse", "Les femmes préfèrent les groupes aux personnes seules"]'::jsonb, 'Ton environnement encourage ta progression ou renforce ton hésitation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80bb97c5-90cf-434a-a890-08a1daa36c04', 'fr', 'Que se passe-t-il quand tes amis évitent de sortir et de rencontrer de nouvelles personnes ?', '["Ton envie d’aborder s’affaiblit avec le temps", "L’environnement te pousse à l’inaction", "Aborder commence à paraître inhabituel et inutile", "Toutes les réponses ci-dessus"]'::jsonb, 'Entoure-toi de gens qui prennent les devants et qui encouragent l’action plutôt que l’évitement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3863647b-81d5-4ab3-9b63-30861c071216', 'fr', 'Que fait en général un entourage tourné vers la progression ?', '["Il te pousse en avant quand tu hésites", "Il salue tes efforts, pas seulement tes résultats", "Il te garde dans ton confort et ta satisfaction", "Il crée des occasions de rencontrer de nouvelles personnes"]'::jsonb, 'Être entouré de gens qui prennent les devants encourage l’initiative plutôt que l’évitement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b78be7b-c378-4416-a5d7-3266ab3c3dfc', 'fr', 'Comment intégrer l’exposition sociale à ton quotidien ?', '["Dire oui aux propositions même quand tu es fatigué", "Sortir même quand rester chez toi est plus facile", "Rejoindre des groupes même quand tu n’es pas sûr qu’ils te plairont", "Toutes les réponses ci-dessus"]'::jsonb, 'L’exposition sociale grandit grâce à de petits choix répétés : te montrer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('49c55c64-36bd-4961-9847-6467136116c3', 'fr', 'On t’invite à un événement, mais tu es fatigué. Qu’est-ce que tu dois faire passer en premier ?', '["Rester chez toi pour ton confort, à chaque fois", "Y aller quand même pour multiplier les occasions de t’exposer", "Attendre d’avoir une énergie parfaite", "Refuser pour éviter les échanges forcés"]'::jsonb, 'Dire oui malgré la fatigue multiplie les rencontres et les liens possibles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dbe59913-e0d6-4e3f-a500-abe814b9551c', 'fr', 'Comment les liens sociaux se multiplient-ils avec le temps ?', '["Une personne peut en amener beaucoup d’autres", "Les invitations ouvrent de nouveaux environnements", "Chaque échange débouche sur quelque chose"]'::jsonb, 'Un seul lien peut ouvrir des dizaines d’occasions indirectes. Lance-toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a683dd8f-530d-4c64-a862-57d8f10be86b', 'fr', 'Quelles occasions de t’entraîner près de chez toi trouve-t-on dans le quotidien ?', '["Une petite discussion avec le barista de ton café habituel", "Un petit échange avec quelqu’un que tu vois souvent à la salle de sport", "Une remarque dans la file d’attente à la caisse du supermarché", "Toutes les réponses ci-dessus"]'::jsonb, 'Les petits échanges du quotidien réduisent la pression et créent de la régularité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb06d0a0-4845-4ac7-80b4-cca9c98be6a3', 'fr', 'Tu vois le même barista tous les matins. Que pourrais-tu faire pour t’entraîner ?', '["Attendre plutôt une soirée dans un bar", "Éviter de parler pour rester à l’aise", "Faire une petite remarque ou discuter un peu"]'::jsonb, 'Les échanges quotidiens sans pression créent naturellement de l’aisance et des compétences.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('219c6ef8-a1ff-4dbe-8af3-fa8686d0e3c1', 'fr', 'Quel est le principal avantage de t’entraîner dans ton quotidien plutôt que dans les bars le soir ?', '["Ça limite les échanges aux week-ends", "Ça transforme les lieux de ta routine en terrains d’entraînement", "Ça demande une sortie spéciale pour chaque répétition", "Ça garde un enjeu élevé pour de meilleurs résultats"]'::jsonb, 'Les lieux du quotidien offrent des occasions sans fin et sans pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('614a2ff0-a42d-4640-8fe2-752885cd8ed4', 'fr', 'Qu’est-ce que l’« avantage du terrain » dans un contexte social ?', '["L’assurance qui vient du fait d’être en terrain connu", "La preuve sociale et le statut perçu que tu gagnes en étant un habitué reconnu", "L’avantage de connaître les lieux et les gens d’un endroit", "Un niveau de confort qui rend l’approche moins effrayante"]'::jsonb, 'Avantage du terrain = la preuve sociale et le statut d’un habitué reconnu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('91be9da9-35e2-4ee6-a859-ebc43437dadd', 'fr', 'Que montre aux autres le fait d’être un « habitué reconnu » ?', '["Tu as clairement ta place ici", "Les autres t’ont déjà accepté et validé", "Tu as plus d’argent ou de statut que les clients ordinaires", "On peut échanger avec toi sans risque"]'::jsonb, 'Appartenance, validation sociale et sentiment de sécurité = avantage du terrain.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7755c8f9-1d23-4c93-b84c-9bb4a6f5047f', 'fr', 'Comment se construire un avantage du terrain à la salle de sport ?', '["Y aller régulièrement aux mêmes heures pour qu’on te reconnaisse", "Échanger de brefs moments sympathiques avec le personnel et les habitués", "N’échanger qu’avec les personnes qui t’attirent", "Saluer les visages familiers que tu as déjà vus"]'::jsonb, 'Régularité, échanges sympathiques avec le personnel et les habitués, salut aux visages familiers = avantage du terrain qui se construit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4a4122bd-a43e-4662-aef4-08635258b40c', 'fr', 'Quel état d’esprit t’aide le mieux à multiplier les approches ?', '["Chaque répétition apprend quelque chose de positif à ton système nerveux", "Chaque approche doit mener quelque part", "Les résultats comptent plus que l’exposition", "Éviter l’inconfort quand c’est possible"]'::jsonb, 'Chaque échange compte comme un entraînement, quel que soit le résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('659f514c-7bf3-425d-9c1e-cf5df2bb69ef', 'fr', 'Une approche tombe à plat et ne donne rien. Comment dois-tu la voir ?', '["Une répétition utile pour t’habituer", "Un échec qui renforce l’anxiété", "La preuve qu’il te faut de meilleures phrases d’accroche", "Une raison d’arrêter pour aujourd’hui"]'::jsonb, 'Chaque échange, quel que soit le résultat, contribue à un apprentissage positif.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e225e86-4aa9-4111-b01c-711e3725c89f', 'fr', 'Quels comportements t’aident à multiplier efficacement les approches ?', '["Un petit échange par jour", "Attendre de te sentir sûr de toi", "Des répétitions régulières et sans pression", "N’aborder que quand l’attirance est forte"]'::jsonb, 'La régularité et la fréquence comptent plus que l’intensité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b9f59424-635d-4624-ad50-aa3dd25f6855', 'fr', 'Que crée la répétition régulière ?', '["Les connexions neuronales se renforcent avec un comportement répété", "Le comportement passe de « ce que je fais parfois » à « ce que je suis »", "Elle empêche l’anxiété de revenir et l’évitement de s’installer", "Toutes les réponses ci-dessus"]'::jsonb, 'Une pratique régulière protège tes acquis et évite que tes compétences s’émoussent. Reste régulier.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6b9ff5d-fc7a-4e92-91d3-57411235152b', 'fr', 'Que se passe-t-il psychologiquement pendant de longues pauses dans ta pratique ?', '["Tes compétences se renforcent encore", "L’évitement et l’anxiété ont le temps de s’installer", "Les connexions neuronales restent efficaces", "Les progrès s’accumulent automatiquement"]'::jsonb, 'Les pauses laissent à ton esprit le temps de trouver de nouvelles raisons de ne pas agir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dd2cece1-3524-4319-bd95-d773079fa01b', 'fr', 'Quels comportements favorisent une régularité qui dure ?', '["Te fixer un minimum hebdomadaire réaliste", "Attendre de te sentir sûr de toi", "Éviter les longs trous entre deux répétitions", "Compter les petits échanges comme de vraies répétitions"]'::jsonb, 'L’élan compte plus que l’intensité ; les progrès viennent de la continuité, pas des coups d’éclat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3529af51-9b76-41c8-868a-2a04a415dc15', 'fr', 'Que se passe-t-il quand ton identité passe de « je pratique une compétence » à « je suis quelqu’un qui le fait » ?', '["Le comportement devient inséparable de l’image que tu as de toi", "Tu n’as plus besoin qu’on te confirme que tu es bon", "L’action passe de « ce que je fais » à « qui je suis »", "Le courage n’est plus nécessaire, parce qu’il n’y a plus d’écart à franchir"]'::jsonb, 'Inséparable de ton identité, « ce que je fais » → « qui je suis », plus d’écart qui demande du courage = changement d’identité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('242a1957-a048-451a-9da7-8ab630640b24', 'fr', 'Pourquoi aborder « ne demande plus de courage » une fois que c’est devenu automatique ?', '["Tu l’as fait tellement de fois que la peur a complètement disparu", "Il n’y a plus d’écart entre qui tu es et ce que tu fais", "L’assurance tirée de succès répétés élimine toute hésitation", "Tu es devenu tellement doué que le résultat n’a plus d’importance"]'::jsonb, 'Tu ne luttes plus contre ta nature : tu exprimes simplement qui tu es.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('371a7413-becb-4f2b-a50d-96a6e2786c70', 'fr', 'Qu’est-ce qui définit l’esprit d’expérimentation quand tu développes une compétence ?', '["Voir chaque échange comme une performance", "Mesurer la réussite aux résultats", "Voir les échanges comme une collecte de données", "Éviter le refus"]'::jsonb, 'Chaque échange est utile, parce qu’il t’apprend quoi ajuster la prochaine fois.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a3d26a9-590a-4af0-95f0-d6c8c35f7896', 'fr', 'Tu essaies l’humour, et ça tombe à plat deux fois. Que suggère l’esprit d’expérimentation ?', '["L’humour, ce n’est pas pour toi", "Arrêter d’aborder", "Apprendre de meilleures blagues par cœur", "Tester un autre style d’humour ou un autre contexte"]'::jsonb, 'Chaque échange t’apprend quoi ajuster la prochaine fois, même quand ça ne se passe pas bien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28e0261e-75cb-4bdc-917c-8d6e653f374a', 'fr', 'Comment l’esprit d’expérimentation rend-il le refus moins douloureux ?', '["Il lie ton ego à chaque résultat", "Il voit les échanges comme une collecte de données", "Il voit le refus comme une information précieuse"]'::jsonb, 'Les résultats deviennent des occasions d’apprendre, pas la preuve de ta valeur.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0d642fd6-f52e-4ce4-95a1-e14b1034c645', 'fr', 'Pourquoi l’authenticité améliore-t-elle le lien ?', '["Elle garantit l’attirance", "Elle réduit l’anxiété", "Elle libère ton esprit pour écouter et t’ajuster", "Elle évite le refus"]'::jsonb, 'Quand tu arrêtes de jouer un rôle, tu peux vraiment t’impliquer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8b12ca4-eea8-4651-a0ba-a39ced8e6aef', 'fr', 'Tu es naturellement calme et observateur. Quel style de flirt te va le mieux ?', '["Des blagues et de la répartie en rafale", "De longues explications", "Des pauses et un regard soutenu", "Des compliments en permanence"]'::jsonb, 'Ta façon de créer de la tension doit correspondre à ton tempérament.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30871b25-0072-4ec6-a580-9ac5cb667148', 'fr', 'Pourquoi un style authentique marche-t-il mieux que des techniques empruntées ?', '["Il libère des ressources mentales pour un vrai lien", "Il s’appuie sur les forces de ta personnalité", "Il t’oblige à faire semblant pour tenir ton rôle"]'::jsonb, 'L’authenticité réduit l’effort et s’appuie sur ce qui marche déjà pour toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3d6c847d-5687-4a4a-a269-96782bfa828d', 'fr', 'Tes approches se terminent souvent vite, sur des réponses polies. Quel est ton point de blocage ?', '["Réussir l’entrée en matière pour capter son intérêt", "Aller plus loin physiquement", "Faire durer les conversations", "Concrétiser efficacement"]'::jsonb, 'Les résultats changent quand ta pratique se concentre sur le maillon le plus faible de l’échange.')
