insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53171673-bc87-47f9-a580-371caf722388', 'fr', 'Tu réussis l’entrée en matière et tu discutes facilement, mais ça reste amical. Quel est ton point de blocage ?', '["L’entrée en matière", "La fluidité de la conversation", "Introduire de la tension séductrice ou du jeu", "Concrétiser"]'::jsonb, 'Les résultats changent quand ta pratique se concentre sur le maillon le plus faible de l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4195d2ca-e36c-4bd9-bb7e-e178e5d589ca', 'fr', 'Tu lances bien les conversations, mais elles deviennent vite gênantes. Quel est ton point de blocage ?', '["Garder une conversation fluide et la garder impliquée", "Placer tes phrases d’accroche", "Concrétiser et obtenir des numéros", "Aller plus loin physiquement"]'::jsonb, 'Les résultats changent quand ta pratique se concentre sur le maillon le plus faible de l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b31c3930-629e-4aab-974a-035d198918d4', 'fr', 'Comment repérer précisément tes points faibles ?', '["Partir du principe que c’est un problème d’assurance en général", "Observer les moments d’échec qui reviennent d’un échange à l’autre", "Repérer à quel moment les choses se défont à chaque fois"]'::jsonb, 'Les points de blocage apparaissent dans des moments précis où ça coince de façon répétée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e977c9fd-3fd5-421d-b9c4-259a05b8af45', 'fr', 'Quelles stratégies peuvent t’aider à sortir d’un plateau de progression ?', '["Augmenter volontairement la difficulté", "Changer d’environnement", "Faire une longue pause pour retrouver ta motivation", "Te concentrer sur une micro-compétence précise"]'::jsonb, 'De nouveaux défis obligent à s’adapter et à progresser. Les longues pauses renforcent l’évitement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
